import{_ as h,C as s,o as d,c as l,a2 as n,j as r,G as a,a as c}from"./chunks/framework.BgSoyxN5.js";const _=JSON.parse('{"title":"Stock Ideas | Nine Screens That Pick Their Own Companies | TickerForge","description":"Nine recurring stock idea formats, each with a fixed rule, a card built from the data, and a company chosen by the screen rather than by an editor. What each one looks for, what it deliberately does not check, and how a channel publishes them.","frontmatter":{"title":"Stock Ideas | Nine Screens That Pick Their Own Companies | TickerForge","description":"Nine recurring stock idea formats, each with a fixed rule, a card built from the data, and a company chosen by the screen rather than by an editor. What each one looks for, what it deliberately does not check, and how a channel publishes them.","aside":false,"locale":"en","pageClass":"partners-page"},"headers":[],"relativePath":"stock-ideas.md","filePath":"stock-ideas.md","lastUpdated":1788410450000}'),p={name:"stock-ideas.md"},m={class:"partners-wide"},u={class:"partners-post-gallery"},g={class:"partners-wide"};function f(y,e,k,w,v,b){const t=s("PartnerPostImage"),i=s("PartnerCabinetCta"),o=s("PartnerLeadForm");return d(),l("div",null,[e[0]||(e[0]=n('<h1 id="stock-ideas" tabindex="-1">Stock Ideas <a class="header-anchor" href="#stock-ideas" aria-label="Permalink to &quot;Stock Ideas&quot;">​</a></h1><p>Nine recurring formats. Each one has a fixed rule, picks its own company from the same daily snapshot, and prints a card built from that company&#39;s numbers.</p><p>The point is not that the list is long. It is that every idea on it can be checked: the rule is written down, the figures on the card are the ones the rule read, and the same screen runs again next week whether or not last week&#39;s pick worked out.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/stockdiscovery">Run the screens yourself</a><a class="partners-button partners-button--secondary" href="/partners/stock-analysis-and-ideas">Publish these in your channel</a></div><p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, or a promise of investment results.</p><h2 id="what-makes-this-different-from-a-pick-list" tabindex="-1">What Makes This Different From A Pick List <a class="header-anchor" href="#what-makes-this-different-from-a-pick-list" aria-label="Permalink to &quot;What Makes This Different From A Pick List&quot;">​</a></h2><p>Most idea feeds have one thing in common: you cannot tell why a name is on the list, so you cannot tell when it should come off.</p><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>The rule is fixed</span><strong>Written before the company was chosen.</strong><p>Each format states its gate in advance — a score above a threshold, a quality reading that has to hold, a cash flow line that has to be rising. The screen applies it; nobody argues a favourite name past it.</p></div><div class="partners-card"><span>The card is the data</span><strong>Every figure shown is a figure the rule read.</strong><p>The picture is drawn from the same snapshot the screen ran on. It is not stock artwork with a ticker typed over it, and when a figure is missing the card drops the line rather than inventing one.</p></div><div class="partners-card"><span>The limits are printed</span><strong>Each format says what it does not check.</strong><p>The growth screen does not look at price. The value screen does not claim the discount is unearned. Saying so on the post itself is what separates a research format from a tip.</p></div></div><h2 id="how-a-company-gets-picked" tabindex="-1">How A Company Gets Picked <a class="header-anchor" href="#how-a-company-gets-picked" aria-label="Permalink to &quot;How A Company Gets Picked&quot;">​</a></h2><p>One pipeline, nine questions asked of it.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Step 1</span><strong>One daily snapshot</strong><p>Every covered company gets a dated record: business quality, risk, growth, valuation context, ownership, insider activity and timing, all computed the same way for everyone.</p></div><div class="partners-format"><span>Step 2</span><strong>The format&#39;s own gate</strong><p>Each screen filters that snapshot by its own published rule and ranks what survives. Nothing is hand-picked, and the same rule runs on the site, in the channel and in a partner&#39;s post.</p></div><div class="partners-format"><span>Step 3</span><strong>One name, with its evidence</strong><p>The top company that has not run recently becomes the post, with the figures its gate read printed on the card beside it.</p></div></div></div><p>A company can appear on more than one screen, and that is information rather than a duplicate: a name that clears the growth gate and the ownership gate in the same week is a different observation from one that clears only one.</p><h2 id="the-nine-formats" tabindex="-1">The Nine Formats <a class="header-anchor" href="#the-nine-formats" aria-label="Permalink to &quot;The Nine Formats&quot;">​</a></h2><h3 id="recovery-and-quality" tabindex="-1">Recovery and quality <a class="header-anchor" href="#recovery-and-quality" aria-label="Permalink to &quot;Recovery and quality&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Weekly · in Partner Cabinet</span><strong>🔄 Turnaround Detected</strong><p>Quarterly numbers that have started moving the other way after a stretch of decline. A turnaround score reads revenue, margins, cash flow and the balance sheet together, so it moves slowly and it can relapse.</p><p class="partners-format__limit">Does not claim the recovery continues. Many turnarounds relapse.</p></div><div class="partners-format"><span>Weekly · in Partner Cabinet</span><strong>🏆 Triple-Rated</strong><p>One company clearing three fixed gates on the same day: the TickerForge score, the Piotroski F-Score and the Altman Z-Score. The thresholds were set in advance and were not fitted to the name that cleared them.</p><p class="partners-format__limit">Says nothing about price. A company can clear all three and still be expensive.</p></div><div class="partners-format"><span>Weekly · channel only</span><strong>🩺 Balance Sheet Stress</strong><p>The same three gates read the other way — a company failing them together. Published as a caution, not as a short idea.</p><p class="partners-format__limit">Distress is a reading, not a prediction of failure.</p></div></div></div><h3 id="weekly-gems" tabindex="-1">Weekly Gems <a class="header-anchor" href="#weekly-gems" aria-label="Permalink to &quot;Weekly Gems&quot;">​</a></h3><p>Three screens sharing one Monday slot, rotating by week, each asking a different question of the same snapshot.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Weekly · in Partner Cabinet</span><strong>🌱 Growth In The Numbers</strong><p>Revenue, earnings and cash flow all still moving the right way on the trailing twelve months — not on a forecast — with the business quality holding up underneath.</p><p class="partners-format__limit">Does not check price. A company can grow exactly as described and still be priced for more.</p></div><div class="partners-format"><span>Weekly · in Partner Cabinet</span><strong>💰 Below What It Is Worth</strong><p>Priced under a fair value estimate, where the estimate is usable and the quality reading holds. The card shows the price against the estimate and the gap between them.</p><p class="partners-format__limit">A discount is a starting question. The price is often the market pricing a problem the model has not caught.</p></div><div class="partners-format"><span>Weekly · in Partner Cabinet</span><strong>🏛 Quality The Money Is Backing</strong><p>A good business reading where the people who file their trades — insiders, tracked funds, or both — have been adding. The card shows both filing sides and what they are adding into.</p><p class="partners-format__limit">Ownership is a confirmation layer, not a thesis. Filers are early as often as they are right.</p></div></div></div><h3 id="ownership-and-cash" tabindex="-1">Ownership and cash <a class="header-anchor" href="#ownership-and-cash" aria-label="Permalink to &quot;Ownership and cash&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Weekly · in Partner Cabinet</span><strong>👤 Insiders Are Buying</strong><p>Meaningful net open-market buying over recent months, from people who file every transaction. The card shows the gross legs, not only the net, and whether the funds agree.</p><p class="partners-format__limit">Insiders buy for many reasons and are frequently early.</p></div><div class="partners-format"><span>Weekly · channel only</span><strong>👤 Insiders Are Selling</strong><p>The same screen with the sign flipped. Same card, same evidence, opposite direction.</p><p class="partners-format__limit">Selling is routine — diversification and tax bills look identical to conviction in a filing.</p></div><div class="partners-format"><span>Weekly · channel only</span><strong>💸 Cash Flow Says Otherwise</strong><p>Reported earnings negative or thin while free cash flow is still growing. The card gives the Piotroski F-Score its own panel, because that is what separates improving operations from a company harvesting itself.</p><p class="partners-format__limit">Rising cash can be a mispricing or it can be cut investment. The F-Score is the tell, not the headline.</p></div></div></div><h2 id="what-the-cards-look-like" tabindex="-1">What The Cards Look Like <a class="header-anchor" href="#what-the-cards-look-like" aria-label="Permalink to &quot;What The Cards Look Like&quot;">​</a></h2><p>Each format draws its own card from the company&#39;s own numbers.</p>',22)),r("div",m,[r("div",u,[a(t,{src:"/partners/examples/idea-turnaround-sample.png",alt:"TickerForge Turnaround idea card: turnaround score gauge, score composition by block, and the business reading underneath",caption:"Turnaround — the score, and which blocks it came from."}),a(t,{src:"/partners/examples/idea-triple-rated-sample.png",alt:"TickerForge Triple-Rated idea card: three quality gates with each threshold marked on its own bar",caption:"Triple-Rated — each gate, with its threshold on the bar."}),a(t,{src:"/partners/examples/idea-gems-growth-sample.png",alt:"TickerForge Weekly Gems Growth idea card: revenue, earnings and cash flow as bars either side of a zero line",caption:"Growth — three lines, each coloured by its own direction."}),a(t,{src:"/partners/examples/idea-gems-value-sample.png",alt:"TickerForge Weekly Gems Value idea card: price against the fair value estimate with the gap between them",caption:"Value — the price, the estimate, and the gap."}),a(t,{src:"/partners/examples/idea-gems-ownership-sample.png",alt:"TickerForge Weekly Gems Ownership idea card: fund and insider activity above the business quality reading",caption:"Ownership — both filing sides, and what they back."}),a(t,{src:"/partners/examples/idea-insider-buying-sample.png",alt:"TickerForge Insiders Are Buying idea card: gross buying and selling legs with the fund side beside them",caption:"Insiders Are Buying — gross legs, not just the net."})])]),e[1]||(e[1]=n('<h2 id="why-a-channel-publishes-these" tabindex="-1">Why A Channel Publishes These <a class="header-anchor" href="#why-a-channel-publishes-these" aria-label="Permalink to &quot;Why A Channel Publishes These&quot;">​</a></h2><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>Rhythm</span><strong>The screens choose the topic.</strong><p>A recurring format means there is something to publish on schedule without hunting for a subject, and readers learn to expect it.</p></div><div class="partners-card"><span>Credibility</span><strong>Evidence under your own conclusion.</strong><p>You keep your voice and your view. The card supplies the figures underneath, and the printed limits are what stop a research post from reading like a tip.</p></div><div class="partners-card"><span>Measurable</span><strong>Every post carries a tracked link.</strong><p>Clicks, bot starts and referral attribution are visible in the Partner Cabinet, so a format that is not working can be dropped on evidence.</p></div></div><p>Six of the nine generate from the Partner Cabinet with one tap. The three marked channel-only are published by TickerForge but not generated under a partner&#39;s name: two of them are negative readings, and publishing &quot;this company is in distress&quot; under your own byline is a different editorial act from publishing an idea.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/partners/stock-analysis-and-ideas">See the partner formats</a><a class="partners-button partners-button--secondary" href="/market-intelligence/">Market reads, not company ideas</a></div>',4)),a(i,{locale:"en"}),e[2]||(e[2]=r("h2",{id:"pilot",tabindex:"-1"},[c("Publish These In Your Channel "),r("a",{class:"header-anchor",href:"#pilot","aria-label":'Permalink to "Publish These In Your Channel {#pilot}"'},"​")],-1)),e[3]||(e[3]=r("p",null,"Every format above is generated with your own tracked link inside it, in one tap, from the Partner Cabinet. Tell us where you publish and which formats your audience would actually read.",-1)),r("div",g,[a(o,{source:"stock_ideas",defaultProgram:"TELEGRAM_RESEARCH"})]),e[4]||(e[4]=n('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><p><a href="/partners/stock-analysis-and-ideas">Stock Analysis &amp; Ideas partners</a> — what a pilot includes and how it is measured.</p></li><li><p><a href="/market-intelligence/">Market Intelligence</a> — the five recurring reads on market conditions rather than individual companies.</p></li><li><p><a href="/stockdiscovery">Stock Discovery</a> — run the same screens yourself, on the same snapshot.</p></li><li><p><a href="/methodology/tickerforge-score">TickerForge Score</a> and <a href="/methodology/risk-score">Risk Score</a> — how the readings behind these gates are built.</p></li></ul>',2))])}const P=h(p,[["render",f]]);export{_ as __pageData,P as default};
